CREATE TYPE "SaleStatus" AS ENUM ('DRAFT','COMPLETED','CANCELLED');
CREATE TYPE "SaleItemType" AS ENUM ('PRODUCT','SERVICE');
CREATE TYPE "PaymentMethod" AS ENUM ('CASH','CARD','BANK_TRANSFER','OTHER');
CREATE TYPE "PaymentStatus" AS ENUM ('PENDING','COMPLETED','FAILED','CANCELLED');
CREATE TABLE "Sale" ("id" TEXT NOT NULL,"businessId" TEXT NOT NULL,"saleNumber" TEXT NOT NULL,"customerId" TEXT,"bookingId" TEXT,"status" "SaleStatus" NOT NULL DEFAULT 'DRAFT',"currency" TEXT NOT NULL DEFAULT 'EUR',"subtotalMinor" INTEGER NOT NULL,"discountMinor" INTEGER NOT NULL DEFAULT 0,"taxMinor" INTEGER NOT NULL,"totalMinor" INTEGER NOT NULL,"createdByUserId" TEXT NOT NULL,"soldAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Sale_pkey" PRIMARY KEY ("id"),CONSTRAINT "Sale_money_check" CHECK ("subtotalMinor">=0 AND "discountMinor">=0 AND "discountMinor"<="subtotalMinor" AND "taxMinor">=0 AND "totalMinor">=0 AND "totalMinor"="subtotalMinor"-"discountMinor"+"taxMinor"));
CREATE TABLE "SaleItem" ("id" TEXT NOT NULL,"saleId" TEXT NOT NULL,"type" "SaleItemType" NOT NULL,"productId" TEXT,"serviceId" TEXT,"description" TEXT NOT NULL,"quantity" INTEGER NOT NULL,"unitPriceMinor" INTEGER NOT NULL,"lineTotalMinor" INTEGER NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "SaleItem_pkey" PRIMARY KEY ("id"),CONSTRAINT "SaleItem_values_check" CHECK ("quantity">0 AND "unitPriceMinor">=0 AND "lineTotalMinor"="quantity"*"unitPriceMinor"),CONSTRAINT "SaleItem_reference_check" CHECK (("type"='PRODUCT' AND "productId" IS NOT NULL AND "serviceId" IS NULL) OR ("type"='SERVICE' AND "serviceId" IS NOT NULL AND "productId" IS NULL)));
CREATE TABLE "Payment" ("id" TEXT NOT NULL,"businessId" TEXT NOT NULL,"saleId" TEXT NOT NULL,"method" "PaymentMethod" NOT NULL,"status" "PaymentStatus" NOT NULL DEFAULT 'COMPLETED',"amountMinor" INTEGER NOT NULL,"reference" TEXT,"paidAt" TIMESTAMP(3),"createdByUserId" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Payment_pkey" PRIMARY KEY ("id"),CONSTRAINT "Payment_amount_check" CHECK ("amountMinor">0));
CREATE UNIQUE INDEX "Sale_businessId_saleNumber_key" ON "Sale"("businessId","saleNumber");
CREATE INDEX "Sale_businessId_createdAt_idx" ON "Sale"("businessId","createdAt");CREATE INDEX "Sale_businessId_status_soldAt_idx" ON "Sale"("businessId","status","soldAt");CREATE INDEX "Sale_customerId_idx" ON "Sale"("customerId");CREATE INDEX "Sale_bookingId_idx" ON "Sale"("bookingId");CREATE INDEX "SaleItem_saleId_idx" ON "SaleItem"("saleId");CREATE INDEX "SaleItem_productId_idx" ON "SaleItem"("productId");CREATE INDEX "SaleItem_serviceId_idx" ON "SaleItem"("serviceId");CREATE INDEX "Payment_businessId_createdAt_idx" ON "Payment"("businessId","createdAt");CREATE INDEX "Payment_saleId_status_idx" ON "Payment"("saleId","status");CREATE INDEX "Payment_createdByUserId_idx" ON "Payment"("createdByUserId");
ALTER TABLE "Sale" ADD CONSTRAINT "Sale_businessId_fkey" FOREIGN KEY ("businessId") REFERENCES "Business"("id") ON DELETE RESTRICT ON UPDATE CASCADE;ALTER TABLE "Sale" ADD CONSTRAINT "Sale_customerId_fkey" FOREIGN KEY ("customerId") REFERENCES "Customer"("id") ON DELETE RESTRICT ON UPDATE CASCADE;ALTER TABLE "Sale" ADD CONSTRAINT "Sale_bookingId_fkey" FOREIGN KEY ("bookingId") REFERENCES "Booking"("id") ON DELETE RESTRICT ON UPDATE CASCADE;ALTER TABLE "Sale" ADD CONSTRAINT "Sale_createdByUserId_fkey" FOREIGN KEY ("createdByUserId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;ALTER TABLE "SaleItem" ADD CONSTRAINT "SaleItem_saleId_fkey" FOREIGN KEY ("saleId") REFERENCES "Sale"("id") ON DELETE RESTRICT ON UPDATE CASCADE;ALTER TABLE "SaleItem" ADD CONSTRAINT "SaleItem_productId_fkey" FOREIGN KEY ("productId") REFERENCES "Product"("id") ON DELETE RESTRICT ON UPDATE CASCADE;ALTER TABLE "SaleItem" ADD CONSTRAINT "SaleItem_serviceId_fkey" FOREIGN KEY ("serviceId") REFERENCES "Service"("id") ON DELETE RESTRICT ON UPDATE CASCADE;ALTER TABLE "Payment" ADD CONSTRAINT "Payment_businessId_fkey" FOREIGN KEY ("businessId") REFERENCES "Business"("id") ON DELETE RESTRICT ON UPDATE CASCADE;ALTER TABLE "Payment" ADD CONSTRAINT "Payment_saleId_fkey" FOREIGN KEY ("saleId") REFERENCES "Sale"("id") ON DELETE RESTRICT ON UPDATE CASCADE;ALTER TABLE "Payment" ADD CONSTRAINT "Payment_createdByUserId_fkey" FOREIGN KEY ("createdByUserId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
